/** Named original OBJ parts, finger pivots, pulsing runes, gems, and the stored animated node. */
public class PrimordialRenderer extends BlockEntityWithoutLevelRenderer {
 static final ResourceLocation OBJ=new ResourceLocation("witchinggadgets","models/gauntlet.obj"),TEXTURE=new ResourceLocation("witchinggadgets","textures/models/primordialbracelet.png"),WHITE=new ResourceLocation("witchinggadgets","textures/models/white.png"),RUNES=new ResourceLocation("witchinggadgets","textures/gui/bracelet.png"),NODES=new ResourceLocation("thaumcraft","textures/misc/nodes.png");
 static final int[] FINGER_COLORS={0x5d194f,0x67275a,0x713464,0x7b436f,0x84507a,0x8d5e84,0x986c8e,0xa17a99,0xab87a4,0xa17a99,0x986c8e,0x8d5e84,0x84507a,0x7b436f,0x713464,0x67275a};
 public PrimordialRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}
 @Override public void renderByItem(ItemStack s,ItemDisplayContext display,PoseStack p,MultiBufferSource buffers,int light,int overlay){var mc=Minecraft.getInstance();var player=mc.player;long ticks=player==null?System.currentTimeMillis()/50:player.tickCount;boolean first=display.firstPerson();var obj=LegacyObj.get(OBJ);p.pushPose();p.translate(.5,.5,.5);switch(display){case GUI->{/* Forge 1.7.10 INVENTORY_BLOCK helper: 10 pixels per unit, Y/Z inverted. */p.scale(.625f,-.625f,-.625f);p.mulPose(Axis.XP.rotationDegrees(210));p.mulPose(Axis.YP.rotationDegrees(-45));p.mulPose(Axis.XP.rotationDegrees(170));p.mulPose(Axis.YP.rotationDegrees(10));p.mulPose(Axis.ZP.rotationDegrees(-30));p.scale(3,3.5f,3);p.translate(.5,-.6,-.3);}case GROUND->{p.scale(1.5f,1.75f,1.5f);p.translate(0,-.4,0);}case THIRD_PERSON_LEFT_HAND,THIRD_PERSON_RIGHT_HAND->{
   // Undo 1.20 ItemInHandLayer after translateToHand; the builtin/entity model has no display transform.
   boolean left=display==ItemDisplayContext.THIRD_PERSON_LEFT_HAND;
   p.translate(left?1/16f:-1/16f,-.125,.625);
   p.mulPose(Axis.YP.rotationDegrees(-180));
   p.mulPose(Axis.XP.rotationDegrees(90));
   if(left)p.scale(-1,1,1);
   // Restore 1.7.10 RenderPlayer's EQUIPPED_BLOCK branch and ForgeHooksClient's helper.
   p.translate(-.0625,.4375,.0625);
   p.translate(0,.1875,-.3125);
   p.mulPose(Axis.XP.rotationDegrees(20));
   p.mulPose(Axis.YP.rotationDegrees(45));
   p.scale(-.375f,-.375f,.375f);
   p.translate(-.5,-.5,-.5);
   p.mulPose(Axis.YP.rotationDegrees(-45));p.mulPose(Axis.ZP.rotationDegrees(160));p.scale(2.68f,2.68f,2.68f);p.translate(-.434,-.887,-.0014);}case FIRST_PERSON_LEFT_HAND,FIRST_PERSON_RIGHT_HAND->{/* Legacy ItemRenderer rotation/scale and Forge EQUIPPED_BLOCK helper, absent from builtin/entity. */p.mulPose(Axis.YP.rotationDegrees(45));p.scale(.4f,.4f,.4f);p.translate(-.5,-.5,-.5);if(player!=null&&player.isUsingItem()){p.mulPose(Axis.ZP.rotationDegrees(20));p.translate(.5,-.5,0);}p.mulPose(Axis.ZP.rotationDegrees(280));p.mulPose(Axis.XP.rotationDegrees(-60));p.mulPose(Axis.YP.rotationDegrees(-75));p.scale(2,2,-2);p.translate(0,-.85,-.51);if(player!=null)obj.draw("Arm_00",p,buffers.getBuffer(RenderType.entityCutoutNoCull(player.getSkinTextureLocation())),light,overlay,0xffffff,1);p.scale(-1,1,1);}default->{}}
  var base=buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE));obj.draw("Guard_Arm_04",p,base,light,overlay,0xcccccc,1);obj.draw("Guard_Hand_05",p,base,light,overlay,0xcccccc,1);String[] fingers={"Thumb","Index","Middle","Ring","Pinky"};for(int f=0;f<5;f++){p.pushPose();p.translate(f<2?.09375:f==2?.03125:f==3?-.03125:-.09375,.625,f==0?.0833167:-.0913815);if(player!=null&&player.isUsingItem()&&display!=ItemDisplayContext.GUI){p.mulPose(Axis.YP.rotationDegrees(f==0?30:f==1?-30:f==3?20:f==4?40:0));p.mulPose(Axis.XP.rotationDegrees(f==0?80:-80));}obj.draw("Finger_"+fingers[f]+"_f"+f,p,base,light,overlay,0xffffff,1);p.scale(1.00001f,1.00001f,1.00001f);obj.draw("Finger_"+fingers[f]+"_Overlay_f"+f+"_1",p,base,light,overlay,FINGER_COLORS[(int)(ticks%32)/2],1);p.popPose();}
  float pulse=(ticks%32)+1;if(pulse>15)pulse=32-pulse;int level=Math.min(255,Math.max(0,(int)(pulse*.2*255)));p.pushPose();p.scale(1.00001f,1.00001f,1.00001f);obj.draw("Runes_06",p,buffers.getBuffer(RenderType.entityTranslucent(RUNES)),light,overlay,(level<<16)|(level<<8)|level,1);p.popPose();var gems=PrimordialGlove.gems(s);for(int i=0;i<5;i++)if(!gems.get(i).isEmpty()){int color=InfusedGem.color(gems.get(i));if(gems.get(i).isDamaged())color=((color>>16&255)/2<<16)|((color>>8&255)/2<<8)|(color&255)/2;obj.draw("Gem0"+i+"_oval0"+i,p,buffers.getBuffer(RenderType.entityCutoutNoCull(WHITE)),light,overlay,color,1);}
  if(first){p.pushPose();p.translate(.1,.675,0);int selected=PrimordialGlove.selected(s);if(!gems.get(selected).isEmpty()){p.pushPose();p.mulPose(Axis.XP.rotationDegrees(-90));p.mulPose(Axis.YP.rotationDegrees(-90));p.translate(-.1875,.147,0);p.translate(selected<2?.09375:selected==3?.0125:.035,0,selected==0||selected==2?.05625:selected==1||selected==4?.14:.1);p.mulPose(Axis.XP.rotationDegrees(45));var gem=gems.get(selected);int frame=(int)(System.currentTimeMillis()/64%32);quad(p,buffers,.025f,0,frame,gem.isDamaged()?3:0,InfusedGem.color(gem),1,true);quad(p,buffers,.025f,-.001f,frame,gem.isDamaged()?3:4,InfusedGem.color(gem),1,true);p.popPose();}p.popPose();}
  if(display!=ItemDisplayContext.GUI){if(first)p.translate(.1,0,0);p.translate(0,.675,0);if(first){p.mulPose(Axis.YP.rotationDegrees(-90));p.mulPose(Axis.XP.rotationDegrees(-40));p.translate(0,-.01,.05);}else if(display==ItemDisplayContext.GROUND)p.mulPose(mc.getEntityRenderDispatcher().cameraOrientation());else if(player!=null){p.mulPose(Axis.YP.rotationDegrees(90+player.yBodyRot-mc.gameRenderer.getMainCamera().getYRot()));p.mulPose(Axis.XP.rotationDegrees(mc.gameRenderer.getMainCamera().getXRot()));}node(s,p,buffers,false);}p.popPose();
 }
 public static void node(ItemStack s,PoseStack p,MultiBufferSource buffers,boolean gui){if(!s.hasTag()||!s.getTag().contains("storedNode"))return;var aspects=PrimordialGlove.stored(s);var tag=s.getTag().getCompound("storedNode");int modifier=tag.getInt("modifier"),type=tag.getInt("type");float ticks=Minecraft.getInstance().player==null?0:Minecraft.getInstance().player.tickCount;float alpha=modifier==0?1.5f:modifier==1?.66f:modifier==2?(float)Math.sin(ticks/3)*.25f+.33f:1;int count=0;float running=0,average=aspects.isEmpty()?1:aspects.total()/(float)aspects.size();for(var a:aspects.aspects()){running+=aspects.amount(a);float oscillation=2*((System.currentTimeMillis()+count*512)%4096)/4096f;if(oscillation>1)oscillation=2-oscillation;float radius=gui?(10+8*oscillation*aspects.amount(a)/average)/120f:.075f+.05f*oscillation*aspects.amount(a)/running;int frame=(int)(System.currentTimeMillis()/64%32)+count*4;quad(p,buffers,radius,-count*.001f,frame,0,a.color(),gui?.25f:Math.min(1,alpha*(a.blendFactor()==771?1.5f:1)),gui||a.blendFactor()==771);count++;}int row=type==2?6:type==3?2:type==4?5:type==5?4:type==6?3:1;quad(p,buffers,gui?10/120f:.0825f,-count*.001f,(int)(System.currentTimeMillis()/64%32),row,0xffffff,1,type==0||type==3||type==4);}
 static void quad(PoseStack p,MultiBufferSource buffers,float radius,float z,int frame,int row,int rgb,float alpha,boolean transparent){var out=buffers.getBuffer(tc4revival.client.TCRenderTypes.node(NODES,transparent));float u=Math.floorMod(frame,32)/32f;for(float[] v:new float[][]{{-radius,radius,u,(row+1)/32f},{radius,radius,u+1/32f,(row+1)/32f},{radius,-radius,u+1/32f,row/32f},{-radius,-radius,u,row/32f}})out.vertex(p.last().pose(),v[0],v[1],z).color(rgb>>16&255,rgb>>8&255,rgb&255,(int)(255*alpha)).uv(v[2],v[3]).uv2(LightTexture.FULL_BRIGHT).endVertex();}
}
